CREATE OR REPLACE FUNCTION public.offsite_promover(_id uuid,_indice integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r offsite_respostas; v uuid; p jsonb; BEGIN IF NOT offsite_admin() THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM offsite_respostas WHERE id=_id FOR UPDATE; p:=r.respostas->'4.3'->_indice; IF p IS NULL OR coalesce(p->>'Nome','')='' THEN RAISE EXCEPTION 'Proposta sem nome'; END IF; INSERT INTO offsite_backlog(resposta_id,proposta_indice,proposta,criado_por) VALUES(_id,_indice,p,auth.uid()) ON CONFLICT(resposta_id,proposta_indice) DO NOTHING; SELECT id INTO v FROM offsite_backlog WHERE resposta_id=_id AND proposta_indice=_indice; RETURN v; END $$;